begin;
set local lock_timeout = '10s';
set local statement_timeout = '120s';

alter table public.stack127_pages drop constraint stack127_pages_page_family_check;
update public.stack127_pages set page_family='site' where page_family in ('info','legal');
update public.stack127_pages page set page_family='directory'
where page.page_family='catalog' and not exists (
  select 1 from public.stack127_tool_catalogs catalog where catalog.page_id=page.id
);
alter table public.stack127_pages add constraint stack127_pages_page_family_check
  check (page_family in ('tool','directory','course','catalog','site'));

alter table public.stack127_tool_catalogs rename to stack127_catalog_pages;
alter table public.stack127_catalog_pages rename constraint stack127_tool_catalogs_pkey to stack127_catalog_pages_pkey;
alter table public.stack127_catalog_pages rename constraint stack127_tool_catalogs_page_id_fkey to stack127_catalog_pages_page_id_fkey;
alter table public.stack127_catalog_pages rename constraint stack127_tool_catalogs_copy_check to stack127_catalog_pages_copy_check;
alter table public.stack127_catalog_pages rename constraint stack127_tool_catalogs_asset_check to stack127_catalog_pages_asset_check;
alter trigger stack127_tool_catalogs_row_updated_at on public.stack127_catalog_pages rename to stack127_catalog_pages_row_updated_at;

alter table public.stack127_catalog_pages add column card_name text, add column card_description text;
alter table public.stack127_catalog_pages disable trigger stack127_touch_catalog_content;
update public.stack127_catalog_pages content set card_name=page.label,card_description=page.meta_description
from public.stack127_pages page where page.id=content.page_id;
alter table public.stack127_catalog_pages enable trigger stack127_touch_catalog_content;
alter table public.stack127_catalog_pages
  alter column card_name set not null, alter column card_description set not null,
  add constraint stack127_catalog_pages_card_copy_check check (
    card_name=btrim(card_name) and length(card_name)>0
    and card_description=btrim(card_description) and length(card_description)>0
  );

create or replace function public.stack127_validate_tool_catalog_page()
returns trigger language plpgsql set search_path=pg_catalog as $$
begin
  if not exists (select 1 from public.stack127_pages where id=new.page_id and page_family='catalog') then
    raise exception 'stack127_catalog_pages.page_id must refer to a catalog page';
  end if;
  return new;
end;
$$;
create or replace function public.stack127_protect_tool_catalog_family()
returns trigger language plpgsql set search_path=pg_catalog as $$
begin
  if old.page_family='catalog' and new.page_family<>'catalog'
    and exists (select 1 from public.stack127_catalog_pages where page_id=old.id) then
    raise exception 'remove the stack127_catalog_pages row before changing its page family';
  end if;
  return new;
end;
$$;

create table public.stack127_directory_pages (
  page_id bigint primary key references public.stack127_pages(id) on delete cascade,
  title text not null,
  intro_markdown text not null,
  content_markdown text,
  content_revision integer not null default 1,
  card_name text not null,
  card_description text not null,
  row_updated_at timestamptz not null default now(),
  constraint stack127_directory_pages_title_check check (title=btrim(title) and length(title)>0),
  constraint stack127_directory_pages_intro_check check (intro_markdown=btrim(intro_markdown) and length(intro_markdown)>0),
  constraint stack127_directory_pages_content_check check (content_markdown is null or (content_markdown=btrim(content_markdown) and length(content_markdown)>0)),
  constraint stack127_directory_pages_revision_check check (content_revision>0),
  constraint stack127_directory_pages_card_check check (
    card_name=btrim(card_name) and length(card_name)>0
    and card_description=btrim(card_description) and length(card_description)>0
  )
);

create function public.validate_stack127_directory_page_family()
returns trigger language plpgsql set search_path=pg_catalog as $$
begin
  perform 1 from public.stack127_pages where id=new.page_id and page_family='directory';
  if not found then raise exception 'stack127_directory_pages.page_id must refer to a directory page'; end if;
  return new;
end;
$$;
create trigger validate_stack127_directory_page_family
before insert or update of page_id on public.stack127_directory_pages
for each row execute function public.validate_stack127_directory_page_family();

create function public.protect_stack127_directory_page_family()
returns trigger language plpgsql set search_path=pg_catalog as $$
begin
  if old.page_family='directory' and new.page_family<>'directory'
    and exists (select 1 from public.stack127_directory_pages where page_id=old.id) then
    raise exception 'remove the stack127_directory_pages row before changing its page family';
  end if;
  return new;
end;
$$;
create trigger protect_stack127_directory_page_family
before update of page_family on public.stack127_pages
for each row execute function public.protect_stack127_directory_page_family();

create function public.prepare_stack127_directory_page_update()
returns trigger language plpgsql set search_path=pg_catalog as $$
begin
  if (new.title,new.intro_markdown,new.content_markdown) is distinct from (old.title,old.intro_markdown,old.content_markdown) then
    new.content_revision=old.content_revision+1;
  elsif new.content_revision<>old.content_revision then
    raise exception 'content_revision changes only with title or Markdown content';
  end if;
  return new;
end;
$$;
create trigger prepare_stack127_directory_page_update
before update on public.stack127_directory_pages
for each row execute function public.prepare_stack127_directory_page_update();
create trigger set_stack127_directory_pages_row_updated_at
before update on public.stack127_directory_pages
for each row execute function public.set_row_updated_at();

alter table public.stack127_directory_pages enable row level security;
create policy "Published directory pages are readable"
on public.stack127_directory_pages for select to anon,authenticated using (
  exists (select 1 from public.stack127_pages page where page.id=page_id and page.page_family='directory' and page.is_published)
);
revoke all on public.stack127_directory_pages from public,anon,authenticated;
grant select on public.stack127_directory_pages to anon,authenticated;
grant select,insert,update,delete on public.stack127_directory_pages to service_role;

-- Copy exported from the page code and shortcut records before the restructure.
insert into public.stack127_directory_pages (page_id,title,intro_markdown,content_markdown,card_name,card_description)
select page.id,copy.title,copy.intro_markdown,copy.content_markdown,page.label,page.meta_description
from jsonb_to_recordset($copy$[{"slug":"ad-networks","title":"Ad networks and their publisher sites","intro_markdown":"Explore ad networks and the websites verified for each one. Counts include confirmed relationships only.","content_markdown":null},{"slug":"cli-apps","title":"A directory of <mark>terminal apps</mark> worth knowing","intro_markdown":"Command-line tools, TUI apps, shells, prompts, and AI agents that run in or beside a terminal. The list includes open-source and closed tools, free and paid ones.","content_markdown":null},{"slug":"epp-status-codes","title":"Domain <mark>status codes</mark> explained","intro_markdown":"Every domain carries status codes, and they are usually why a transfer is refused, a site suddenly goes dark, or a registrar dashboard shows something alarming. They are written for software rather than people. Here is what each one means in plain terms, who set it, whether you can remove it yourself, and what to do about it.","content_markdown":"<!-- section:copy-1 -->\n## Why is the same code written two different ways?\n\nYou will see these in two spellings and they are the same thing. Your registrar and older tools show `clientTransferProhibited`. The modern registry data shows  `client transfer prohibited`. Nothing has changed except the formatting, so both are listed below.\n\nOne that trips people up: `ok` and `active` are also the same status, not two different ones.\n\n<!-- section:copy-2 -->\n## What is the difference between client and server status codes?\n\nThis is the useful split. Codes starting with `client` were set by your registrar, which means there is usually a switch in your account that turns them off. Codes starting with `server` were set by the registry that runs the ending, and no amount of clicking in your account will move them. If you are stuck, that prefix tells you whether to look in your own settings or pick up the phone.\n\n`client…` → your registrar, usually yours to change\n\n`server…` → the registry, not yours to change\n\n<!-- section:copy-3 -->\n## My domain is registered but the site is down. Why?\n\nCheck for `client hold` or `server hold` first. Those two tell the registry to stop publishing the domain, so nothing under it resolves at all, while the registration itself remains perfectly valid. People lose hours in DNS tools before finding it, because DNS is not the problem. `client hold` is nearly always unpaid invoices or an unverified contact address.\n\nThe other one worth knowing: `inactive` means no nameservers are on record. It looks alarming and usually is not, it just means nothing has been pointed anywhere yet.\n\n<!-- section:copy-4 -->\n## Why was this status code set on my domain?\n\nWhy it was set. `server transfer prohibited` could be a trademark dispute, a court order, a registry security action, or a lock you asked for yourself and forgot about. The code carries no reason and the reason is not published anywhere public. Your registrar can usually find out.\n\nRegistries occasionally publish codes that are entirely their own invention and appear in no standard. Those are shown exactly as the registry returned them, marked as having no explanation available, rather than being matched to something plausible-looking. If you hit one, the registry that runs the ending is the only place it is documented.\n\n<!-- section:copy-5 -->\n## Are status codes on my domain a bad sign?\n\nUsually not. A healthy domain normally carries at least one, and  `clientTransferProhibited` is the default lock most registrars apply precisely because it protects you from an unauthorised transfer. Seeing it is a good sign, not a problem to fix.\n\nThe ones actually worth acting on are the two hold codes, anything starting with `server`, and the lifecycle codes that mean a domain is on its way out. Everything else is either informational or something that clears on its own.\n\n<!-- section:copy-6 -->\n## Related tools\n\nThe [registration lookup](/domain-lookup) shows every status on a domain alongside the rest of its record. If you are specifically trying to move a domain, the  [transfer readiness check](/transfer-readiness)  works out which of these are actually in your way, and for the life cycle codes the [expiry checker](/domain-expiry) lays out the stages in order.\n\nICANN also publishes  [its own reference for these codes](https://www.icann.org/resources/pages/epp-status-codes-2014-06-16-en) , which is worth reading if you want the formal definitions rather than the practical ones."},{"slug":"launch-directories","title":"Find the right place to <mark>launch your product</mark>","intro_markdown":"Compare cost, review time, link type, and who can submit. Then open the site's own submission page.","content_markdown":"<!-- section:guide-1 -->\n## How we check each listing\n\nFor each site, we look for its official submission page, pricing, and rules, and use the ones that load. When we can open a published listing, we check the link it gives the maker's site. Some sites blocked us, needed a login, or had no listing we could open. Those details stay marked Couldn't verify or Not stated on their site. We don't guess them.\n\nOpen a card to see its full details and each page we used. A source shows its own check date when we have one. The record date is the last time we checked anything on that place, so some sources can be older.\n\nCost on a card shows the lowest price we found. \"From\" means higher plans exist, and \"once\" means a one-time fee. Open a card to see every price. When a site doesn't publish a price, the card says Not stated. When we couldn't check it, the card says Couldn't verify.\n\nPrices, review times, and link rules change. Check the site's own page before you pay.\n\n### How is the recommended order chosen?\n\nA few long-running launch sites come first: Product Hunt, BetaList, DevHunt, Peerlist Launchpad, AlternativeTo, and SaaSHub. After those, places with a working submission page come before places without one. Launch boards and beta sites come before broader listings, and niche directories come last. Within each group, a free option comes first, then a dofollow link.\n\nThe order doesn't mean one site will bring you more traffic than another. Use the category filter to see the places that fit your product.\n\n### What do the link types mean?\n\n<!-- section:guide-2 -->\nA link result only covers the named sample listing, or the plan the site's terms describe. Free and paid listings can differ.\n\nTwo labels mean we have no confirmed link result:\n\n<!-- section:guide-3 -->\n### What do the missing-detail labels mean?\n\n<!-- section:guide-4 -->\n### Found something wrong?\n\nEmail [stack127@proton.me](mailto:stack127@proton.me) with the site name and the page that shows the right answer. Each place's details also have a correction link."},{"slug":"local-security-cameras","title":"Local security cameras for <mark>Frigate and Home Assistant</mark>","intro_markdown":"Compare camera models by RTSP or ONVIF, resolution, and power. Check the listed Frigate status before using a stream setup.","content_markdown":"## Before you buy\n\nSome camera details come from published records and have not been tested on our own camera. Check the Frigate status and exact stream details before setup."},{"slug":"matter-devices","title":"Matter devices with <mark>certification evidence</mark>","intro_markdown":"Search Matter-compatible devices by manufacturer, category, transport, and certificate ID. Certification confirms the standard record, but Home Assistant may expose fewer optional features than another controller.","content_markdown":"## Before you buy\n\nMatter certification confirms the product is certified. Home Assistant may still expose fewer features than another controller."},{"slug":"nut-compatible-ups","title":"UPS models with <mark>Network UPS Tools drivers</mark>","intro_markdown":"Check whether Network UPS Tools supports your UPS model, which driver it uses, and how it connects. Product family entries may not cover every model.","content_markdown":"## Before you buy\n\nCheck the driver and connection for your exact model. A product family listing may not cover every model or regional version."},{"slug":"self-host-apps","title":"Self-host <mark>apps that fit</mark> your server, storage, and setup comfort","intro_markdown":"Browse open-source, source-available, and closed-source apps by purpose, setup, resource needs, price, and maintenance.","content_markdown":null},{"slug":"software-licenses-for-self-hosting","title":"Software <mark>licenses</mark> for self-hosting","intro_markdown":"Compare the licenses used by self-hosted apps. See whether you can run each app at home or at work, modify it, redistribute it, or host it for other people.","content_markdown":"<!-- section:copy-1 -->\n## Compare software licenses\n\nThe table answers the decisions that matter when you run, change, or redistribute a self-hosted app. It reports what each license permits, not what a company policy will approve.\n\n<!-- section:copy-2 -->\n### What the verdicts mean\n\n**The columns**\n\n- **Self-host**: can you run it on your own hardware, for yourself and your household?\n - **Company**: can it run on a work server, for internal business use, in production?\n - **OSI**: is it OSI-approved open source? `pd` means a public-domain dedication that works like open source without being on the approved list.\n - **Service**: can you host it for people outside your household or company, including paid hosting?\n - **Modify**: can you change the code, and what do you owe when those changes leave your server?\n - **Redistribute**: can you pass the software on, in images, appliances, forks, or products?\n - **Copyleft**: whether conditions travel with the code, and how far.\n\n**The values**\n\n- **yes**: the activity is permitted. Routine notices or attribution may still apply.\n - **careful**: permitted with a material obligation such as source disclosure, share-alike, or a competition limit. The card below spells it out.\n - **depends**: project-specific parameters, a chosen option, or separate terms decide.\n - **no**: blocked by the license.\n\n**One rule this table follows:** it reports what the license permits, not what a legal department will approve. WTFPL permits everything and plenty of companies still ban it. That is a policy problem, not a licensing one, and the card says so. The [self-host apps](/self-host-apps) directory uses the same short names.\n\n<!-- section:copy-3 -->\n## The four families\n\n<!-- section:copy-4 -->\nEvery license above belongs to one of four families, and the family answers most questions on its own. What separates them is one thing:  **what you owe when the software leaves your hands.**\n\n**Permissive** asks only that copyright notices survive redistribution. Your fork can stay closed forever.\n\n**Weak copyleft** scopes the share-back duty to the covered code. Distribute modified MPL files or a changed LGPL library and that source stays open. The rest of your product stays yours.\n\n**Copyleft** covers the whole program, and the trigger is the part people get wrong.\n\n**Restricted** is source-available, not open source. The code is public, but different licenses limit different uses. SSPL conditions a service offering on releasing service source. Elastic-2.0 and many Sustainable Use terms directly limit managed services. BSL 1.1, FSL, and PolyForm turn on project parameters, a conversion date, or whether your use competes with the publisher. Self-hosting for yourself or your company is usually the intended free path, but the exact text still controls.\n\n<!-- section:copy-5 -->\n## The copyleft trigger\n\nGPL compliance starts when you **distribute** a covered copy. Modification is not required: distributing an unmodified copy can still require license notices and, for object code, corresponding source.\n\nAGPL adds a network trigger in  [section 13](https://www.gnu.org/licenses/agpl-3.0.html#section13) . When people use your modified version over a network, you must offer them its corresponding source.\n\nThat clause stops a modified hosted clone from staying closed, which makes AGPL a common choice for self-host web apps.\n\nTwo things follow that are worth stating plainly, because both get misread constantly:\n\n- Unmodified upstream does not trigger AGPL section 13, even when family, coworkers, or other remote users log in.\n - The extra network rule needs **modified** code plus remote interaction. If you are the only user, there is no section 13 source-offer duty.\n\n<!-- section:copy-6 -->\n## Every license, family by family\n\nThe licenses below are grouped by family, with links to the official text and popular self-hosted apps that use each one.\n\n<!-- section:copy-7 -->\n## Open source or source-available?\n\n**Open source**, under the  [Open Source Definition](https://opensource.org/osd) , lets anyone use, study, change, and share the software for any purpose, including commercial use. MIT, Apache-2.0, GPL, and AGPL qualify. Requiring source code under a copyleft license is not the same as restricting use.\n\n**Source-available** means the code is public, but the terms add limits that open-source licenses cannot. SSPL, Elastic License, BSL, FSL, and PolyForm each restrict a different kind of use or depend on project-specific terms.\n\nA public repository and a free download prove neither one. Read the license grant, especially before company use, redistribution, or paid hosting.\n\n<!-- section:copy-8 -->\n## Choosing a license for your own app: the short path\n\nIf you are shipping a self-host app and want one answer rather than thirty:\n\n- **You want maximum adoption and do not care who profits.** MIT. Apache-2.0 if you want an explicit patent grant.\n - **You want fixes shared back but not a fight over combined products.**  MPL-2.0.\n - **You are shipping a library.** LGPL-3.0, or MIT if you want it everywhere.\n - **Your real fear is a hosted closed clone.** AGPL-3.0. This is the common open-source choice for that goal.\n - **You want a commercial business on top.** AGPL-3.0 plus a paid commercial license, dual-licensed.\n - **You need to block managed-service resale specifically, and can accept losing the open-source label.**  BSL 1.1 or FSL, both of which convert to open source later. Elastic-2.0 or Sustainable Use if you do not want a conversion date.\n - **You want personal use free and all company use paid.** PolyForm Noncommercial, understanding business adoption will be small.\n\nWhatever you pick, write a plain-language paragraph next to the LICENSE file explaining what a self-hoster may do. Self-hosters read that paragraph before they read the legal text, and often instead of it.\n\n<!-- section:copy-9 -->\n## Questions that come up\n\n**Does AGPL stop me self-hosting an app for my family?**   \n No for unmodified upstream, and no when you are the only user. If you modify it and someone else, including family, uses it remotely, AGPL section 13 requires you to offer that version's corresponding source.\n\n**I run an unmodified AGPL app and let friends log in. Do I owe them source?**   \n Unmodified upstream does not trigger AGPL section 13. The extra source-offer duty appears when remote users interact with a modified version.\n\n**My company runs a GPL app internally with local patches. Do we have to publish them?**   \n No. GPL triggers on distribution. Internal use is not distribution.\n\n**Is a public GitHub repo open source?**   \n Not necessarily. Check whether the license is OSI-approved. SSPL, BSL, FSL, Elastic, and PolyForm are all public and none of them are open source.\n\n**Can I sell hosting for an MIT-licensed app?**   \n Yes. Permissive licenses do not block that, which is exactly why some projects move to AGPL or a source-available license later.\n\n**Two projects both say BSL 1.1. Do they grant the same rights?**   \n No. The Additional Use Grant and change date differ per project. Read both.\n\n**The repo has no LICENSE file. Can I use it?**   \n First check the README, documentation, or another file for an express license grant.  [GitHub's licensing guidance](https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/licensing-a-repository)  explains the default: if the repository grants no license anywhere, normal copyright applies and you should treat it as all rights reserved.\n\n<!-- section:disclaimer -->\n*This is a practical guide, not legal advice. If money, customers, or a commercial product are involved, read the project's LICENSE file and get legal help when you need it.*"},{"slug":"tld-directory","title":"TLD <mark>directory</mark>: every domain extension, its operator, and DNSSEC","intro_markdown":"Every top-level domain that exists, with the organisation that operates it, whether it is signed with DNSSEC, and whether registration data can be looked up under it. Built directly from IANA's own records and the published root zone rather than copied from another list, and it tells you when it was last refreshed.","content_markdown":"<!-- section:copy-1 -->\n## How many domain extensions are there?\n\n<!-- section:copy-2 -->\n## What are the different types of domain extension?\n\n<!-- section:copy-3 -->\n## Why can some domain extensions not be looked up?\n\nModern registration data is published over a protocol called RDAP, and not every registry offers it. Where an ending has no RDAP service, no tool can answer questions about names under it, including the ones on this site. That is a gap in what the ending publishes rather than a limitation of any particular lookup.\n\nA few endings run RDAP without appearing in the official IANA directory. Those are marked separately in the table, and each one was verified against a real domain by hand before being added. It is a short list because every entry has to be checked rather than guessed at.\n\n<!-- section:copy-4 -->\n## Does DNSSEC on an extension mean my domain is secure?\n\nThis column says whether the ending itself is signed in the root zone, which is measured directly from its DS records. That is a prerequisite for domains under it to use DNSSEC, and it is not the same thing as any particular domain being signed. Nearly every ending is signed now; most individual domains are not.\n\nTo check one domain, the  [DNSSEC chain checker](/dnssec-checker) validates it properly rather than reading a flag.\n\n<!-- section:copy-5 -->\n## Where does this data come from?\n\n- Type and operator: [IANA's root zone database](https://www.iana.org/domains/root/db).\n - DNSSEC: DS records in the published root zone, so it is measured rather than claimed.\n - Lookups: the IANA RDAP directory, plus a short hand-verified list of registries that run RDAP without appearing in it.\n\nThe table is rebuilt from those sources rather than maintained by hand, and the rebuild stops rather than saving a partial result if IANA changes its page structure. That means rows can go out of date, but they will not quietly go wrong, and the refresh date above tells you which you are looking at.\n\n<!-- section:copy-6 -->\n## Why are domain prices not listed?\n\nBecause any price shown here would be wrong. Registry wholesale pricing is not public for most endings, and retail pricing changes constantly with the registrar, the promotion and whether the specific name is classed as premium. A stale price is more misleading than no price, so check at a registrar when you are ready to buy.\n\nRegistration counts are missing for a similar reason: registry reporting is inconsistent and delayed. There are also no rankings, because which ending suits you depends entirely on what you are building and where.\n\n<!-- section:copy-7 -->\n## Related tools\n\nTo check whether a specific name is free under one of these endings, use the  [domain availability checker](/domain-availability), or try one name across several at once with  [multi-TLD availability](/multi-tld-availability). For the full record on a registered domain, use the  [domain registration lookup](/domain-lookup)."},{"slug":"z-wave-devices","title":"Z-Wave devices with <mark>exact product IDs</mark>","intro_markdown":"Search exact Z-Wave models and inspect the identifiers Z-Wave JS uses to select a configuration. Match the frequency region and firmware before buying because a retail name can cover several variants.","content_markdown":"## Before you buy\n\nCheck the product ID, radio region, and firmware against your device before buying or pairing it."},{"slug":"zigbee-coordinators","title":"Zigbee coordinators for <mark>ZHA and Zigbee2MQTT</mark>","intro_markdown":"Compare coordinator models by chipset, connection, and support for ZHA or Zigbee2MQTT. Some changes require pairing your devices again.","content_markdown":"## Before you buy\n\nCheck that the firmware supports your exact adapter before switching. Some changes require pairing your devices again."},{"slug":"zigbee-devices","title":"Zigbee compatible devices for <mark>Zigbee2MQTT and ZHA</mark>","intro_markdown":"Check whether a device is listed for Zigbee2MQTT, has a community report for ZHA, or both. Each card shows its device type and main features.","content_markdown":"<!-- section:copy-1 -->\n## Before you buy\n\nA device listed for Zigbee2MQTT is not automatically confirmed for ZHA. Support can also differ between hardware revisions.\n\n## The exact model matters more than the product name\n\nManufacturers sometimes reuse a product name across different hardware. Tuya devices can also share generic Zigbee identifiers such as `TS0601` while using different manufacturer fingerprints and data points. This directory shares evidence only when the marketed model matches exactly. For Tuya devices, check the manufacturer and model fingerprint as well as the product name.\n\n## Check for support updates\n\nSupport changes with converter releases, Home Assistant updates, device firmware, and hardware revisions. Open the compatibility links in the device details and check the notes for your exact model."},{"slug":"keyboard-shortcuts","title":"<mark>Keyboard shortcuts</mark> for your daily tools","intro_markdown":"Choose an app, check its platforms, and open a printable sheet with the shortcuts already selected.","content_markdown":"<!-- section:copy-1 -->\n## Print the shortcuts you need\n\n[Build a printable sheet from the reference](/shortcuts-cheatsheet-generator)"},{"slug":"keyboard-shortcuts/1password","title":"<mark>1Password</mark> keyboard shortcuts","intro_markdown":"1Password has separate keyboard layers for the desktop app, Quick Access, and the browser extension. The bindings below keep those contexts separate so the same key can be read without guessing where it works.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable 1Password sheet](/shortcuts-cheatsheet-generator?apps=1password)"},{"slug":"keyboard-shortcuts/7-zip","title":"<mark>7-Zip</mark> keyboard shortcuts","intro_markdown":"7-Zip File Manager uses function keys for file work and numeric keypad keys for selection. The official source defines the bindings directly in the File Manager key handler.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable 7-Zip sheet](/shortcuts-cheatsheet-generator?apps=7-zip)"},{"slug":"keyboard-shortcuts/ableton-live","title":"<mark>Ableton Live</mark> keyboard shortcuts","intro_markdown":"Ableton Live's keymap reaches almost every part of a set: views, devices, clips, arrangement editing, tracks, transport, and the browser. The groups follow Live's own manual so a binding stays tied to the view where it works.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Ableton Live sheet](/shortcuts-cheatsheet-generator?apps=ableton-live)"},{"slug":"keyboard-shortcuts/adobe-acrobat-pro","title":"<mark>Adobe Acrobat Pro</mark> keyboard shortcuts","intro_markdown":"Acrobat's desktop keymap covers tool selection, PDF navigation, comments, form work, task panes, bookmarks, search, and accessibility. Focus-sensitive and single-key commands stay grouped with the interface state they require.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Adobe Acrobat Pro sheet](/shortcuts-cheatsheet-generator?apps=adobe-acrobat-pro)"},{"slug":"keyboard-shortcuts/adobe-acrobat-reader","title":"<mark>Adobe Acrobat Reader</mark> keyboard shortcuts","intro_markdown":"Adobe documents one desktop keyboard map for Acrobat Reader and Acrobat. This Reader reference keeps the viewing, commenting, form-entry, search, portfolio, navigation, and accessibility commands, while leaving Acrobat-only authoring tools on the Acrobat Pro page.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Adobe Acrobat Reader sheet](/shortcuts-cheatsheet-generator?apps=adobe-acrobat-reader)"},{"slug":"keyboard-shortcuts/adobe-after-effects","title":"<mark>Adobe After Effects</mark> keyboard shortcuts","intro_markdown":"After Effects assigns shortcuts across the application and inside individual panels. This reference keeps timeline properties, layers, views, tools, keyframes, masks, paint, text, previews, and rendering in separate groups so focus-dependent commands retain their context.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Adobe After Effects sheet](/shortcuts-cheatsheet-generator?apps=adobe-after-effects)"},{"slug":"keyboard-shortcuts/adobe-audition","title":"<mark>Adobe Audition</mark> keyboard shortcuts","intro_markdown":"Audition's published defaults cover transport and zoom, markers, Waveform Editor processing, spectral editing, and Multitrack clip or mixer adjustments. Editor-specific commands stay separate so a binding is not mistaken for an application-wide action.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Adobe Audition sheet](/shortcuts-cheatsheet-generator?apps=adobe-audition)"},{"slug":"keyboard-shortcuts/adobe-illustrator","title":"<mark>Adobe Illustrator</mark> keyboard shortcuts","intro_markdown":"Illustrator's default keymap covers document work, its dense tool palette, artboards, object selection, drawing, color, type, and effects. These tables keep Adobe's Windows and macOS defaults separate.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Adobe Illustrator sheet](/shortcuts-cheatsheet-generator?apps=adobe-illustrator)"},{"slug":"keyboard-shortcuts/adobe-indesign","title":"<mark>Adobe InDesign</mark> keyboard shortcuts","intro_markdown":"InDesign's default shortcuts cover layout tools, frames, transformations, typography, tables, document navigation, panels, styles, and production previews. The same key can change meaning when a text insertion point is active, so context stays in each action.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Adobe InDesign sheet](/shortcuts-cheatsheet-generator?apps=adobe-indesign)"},{"slug":"keyboard-shortcuts/adobe-lightroom-classic","title":"<mark>Adobe Lightroom Classic</mark> keyboard shortcuts","intro_markdown":"Lightroom Classic's keymap follows its module-based workflow. It covers the workspace, catalog and photo management, Library views, ratings, collections, metadata, Develop controls, and local adjustment tools.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Adobe Lightroom Classic sheet](/shortcuts-cheatsheet-generator?apps=adobe-lightroom-classic)"},{"slug":"keyboard-shortcuts/adobe-premiere-pro","title":"<mark>Adobe Premiere Pro</mark> keyboard shortcuts","intro_markdown":"Premiere Pro separates application commands from panel-specific commands. This reference keeps file, edit, clip, sequence, marker, graphics, workspace, mixer, effects, utility-panel, Project, Program Monitor, and Timeline bindings in their working context.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Adobe Premiere Pro sheet](/shortcuts-cheatsheet-generator?apps=adobe-premiere-pro)"},{"slug":"keyboard-shortcuts/adobe-premiere-rush","title":"<mark>Adobe Premiere Rush</mark> keyboard shortcuts","intro_markdown":"Premiere Rush keeps project, clip, timeline, preview, and media-browser commands in separate contexts. This reference preserves those focus boundaries and the few commands that apply only while editing title text.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Adobe Premiere Rush sheet](/shortcuts-cheatsheet-generator?apps=adobe-premiere-rush)"},{"slug":"keyboard-shortcuts/adobe-substance-3d-painter","title":"<mark>Adobe Substance 3D Painter</mark> keyboard shortcuts","intro_markdown":"Substance 3D Painter combines editable application shortcuts with fixed mouse and layer-stack controls. This reference separates tools, viewport navigation, painting gestures, masks, layers, and project commands so each chord keeps its working context.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Adobe Substance 3D Painter sheet](/shortcuts-cheatsheet-generator?apps=adobe-substance-3d-painter)"},{"slug":"keyboard-shortcuts/adobe-xd","title":"<mark>Adobe XD</mark> keyboard shortcuts","intro_markdown":"Adobe XD assigns commands across design, vector editing, layout, prototype preview, and shared-spec contexts. This reference keeps platform-only exports, window controls, and preview recording explicit instead of inventing Windows equivalents.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Adobe XD sheet](/shortcuts-cheatsheet-generator?apps=adobe-xd)"},{"slug":"keyboard-shortcuts/affinity-designer","title":"<mark>Affinity Designer 2</mark> keyboard shortcuts","intro_markdown":"Affinity Designer 2 assigns tools by Persona and combines them with document, view, text, drawing-modifier, and layer controls. Tool letters can be tapped to keep a tool active or held for temporary use before returning to the previous tool.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Affinity Designer 2 sheet](/shortcuts-cheatsheet-generator?apps=affinity-designer)"},{"slug":"keyboard-shortcuts/affinity-photo","title":"<mark>Affinity Photo 2</mark> keyboard shortcuts","intro_markdown":"Affinity Photo 2 changes tool letters with the active Persona while keeping common document, view, brush, and layer commands available throughout the desktop app. This reference labels each Persona so overlapping keys remain understandable.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Affinity Photo 2 sheet](/shortcuts-cheatsheet-generator?apps=affinity-photo)"},{"slug":"keyboard-shortcuts/aider","title":"<mark>Aider</mark> keyboard shortcuts","intro_markdown":"Aider's interactive terminal prompt supports editing, history navigation, interruption, multiline input, and external-editor handoff. Its default Emacs bindings and optional vi command mode are documented separately so the active input mode is always clear.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Aider sheet](/shortcuts-cheatsheet-generator?apps=aider)"},{"slug":"keyboard-shortcuts/airtable","title":"<mark>Airtable</mark> keyboard shortcuts","intro_markdown":"Airtable's documented shortcuts cover base navigation, view controls, cell editing, record movement, and the Gallery, Kanban, Gantt, and expanded-record surfaces. The reference keeps context-specific commands with the view where Airtable says they work.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Airtable sheet](/shortcuts-cheatsheet-generator?apps=airtable)"},{"slug":"keyboard-shortcuts/alfred","title":"<mark>Alfred</mark> keyboard shortcuts","intro_markdown":"Alfred's default hotkeys cover launching and dismissing the search window, acting on results, browsing files, managing the File Buffer, using Clipboard History, and controlling the Music Mini Player. Powerpack requirements are stated where they apply.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Alfred sheet](/shortcuts-cheatsheet-generator?apps=alfred)"},{"slug":"keyboard-shortcuts/amplitude","title":"<mark>Amplitude</mark> keyboard shortcuts","intro_markdown":"Amplitude's chart-creation shortcuts open event and property controls, refresh or save analysis, copy and organize charts, and operate hovered selector rows. Every binding here stays within the chart builder context documented by Amplitude.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Amplitude sheet](/shortcuts-cheatsheet-generator?apps=amplitude)"},{"slug":"keyboard-shortcuts/android-studio","title":"<mark>Android Studio</mark> keyboard shortcuts","intro_markdown":"Android Studio's default keymap covers tool windows, search and navigation, visual layout tools, code generation and editing, builds, debugging, refactoring, and version control. Windows and Linux share one documented column, while macOS has its own combinations.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Android Studio sheet](/shortcuts-cheatsheet-generator?apps=android-studio)"},{"slug":"keyboard-shortcuts/anydesk","title":"<mark>AnyDesk</mark> keyboard shortcuts","intro_markdown":"AnyDesk reserves one Windows hotkey family for controlling an active remote session. Every command begins with Control+Alt+Shift, which keeps local session controls distinct from keystrokes sent to the remote device.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable AnyDesk sheet](/shortcuts-cheatsheet-generator?apps=anydesk)"},{"slug":"keyboard-shortcuts/apple-music","title":"<mark>Apple Music</mark> keyboard shortcuts","intro_markdown":"Apple Music uses different desktop keymaps on Windows and macOS. This reference keeps platform-only playlist, library, window, and access-key commands visible instead of applying a blanket Control-to-Command conversion.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Apple Music sheet](/shortcuts-cheatsheet-generator?apps=apple-music)"},{"slug":"keyboard-shortcuts/apple-notes","title":"<mark>Apple Notes</mark> keyboard shortcuts","intro_markdown":"Notes on Mac provides shortcuts for the main window, note formatting, lists, shared-note navigation, and table editing. Table keys depend on whether the insertion point is inside a cell, so those commands remain in their own group.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Apple Notes sheet](/shortcuts-cheatsheet-generator?apps=apple-notes)"},{"slug":"keyboard-shortcuts/arc-browser","title":"<mark>Arc Browser</mark> keyboard shortcuts","intro_markdown":"Arc organizes browsing around tabs, Spaces, a sidebar, and Split View. This reference preserves the different Windows and macOS navigation chords, including macOS-only Little Arc and alternate history keys.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Arc Browser sheet](/shortcuts-cheatsheet-generator?apps=arc-browser)"},{"slug":"keyboard-shortcuts/asana","title":"<mark>Asana</mark> keyboard shortcuts","intro_markdown":"Asana combines Inbox keys, task actions, Tab-key chords, selection controls, and native desktop-window shortcuts. The list-view field-navigation command is different: Asana explicitly documents it as two Right Arrow presses.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Asana sheet](/shortcuts-cheatsheet-generator?apps=asana)"},{"slug":"keyboard-shortcuts/audacity","title":"<mark>Audacity</mark> keyboard shortcuts","intro_markdown":"Audacity's Standard shortcut set covers projects, audio editing, selections, timeline views, playback, recording, looping, track mute controls, and effect reuse. The extended Full set remains separate because it is not enabled by default.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Audacity sheet](/shortcuts-cheatsheet-generator?apps=audacity)"},{"slug":"keyboard-shortcuts/autocad","title":"<mark>AutoCAD</mark> keyboard shortcuts","intro_markdown":"AutoCAD's default CUIx keymap controls drawings, palettes, selection and editing, drafting aids, viewports, layouts, and 3D subobject filters. This record follows the Windows shortcut table published for AutoCAD 2026.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable AutoCAD sheet](/shortcuts-cheatsheet-generator?apps=autocad)"},{"slug":"keyboard-shortcuts/autodesk-maya","title":"<mark>Autodesk Maya</mark> keyboard shortcuts","intro_markdown":"Maya's default hotkeys cover transform tools, scene files, object display, animation playback, snapping, component selection, editing, panel views, and polygon modeling. Mouse-only camera and marking-menu gestures are kept out of the keyboard tables.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Autodesk Maya sheet](/shortcuts-cheatsheet-generator?apps=autodesk-maya)"},{"slug":"keyboard-shortcuts/autodesk-revit","title":"<mark>Autodesk Revit</mark> keyboard shortcuts","intro_markdown":"Revit uses short letter sequences for modeling, annotation, view, and systems commands. The tables retain Autodesk's alternative sequences and reserved Ctrl combinations where the 2026 default list publishes them.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Autodesk Revit sheet](/shortcuts-cheatsheet-generator?apps=autodesk-revit)"},{"slug":"keyboard-shortcuts/axure-rp","title":"<mark>Axure RP</mark> keyboard shortcuts","intro_markdown":"Axure RP 11's keymap covers files, canvas movement, widget insertion and editing, vector operations, sitemap management, prototype tools, panes, preview, and publishing. Single-key canvas commands remain visible as documented alternatives.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Axure RP sheet](/shortcuts-cheatsheet-generator?apps=axure-rp)"},{"slug":"keyboard-shortcuts/azure-devops","title":"<mark>Azure DevOps</mark> keyboard shortcuts","intro_markdown":"Azure DevOps web shortcuts change with the active service and page. Sequential navigation keys work only when focus is outside an input control, so this reference separates global navigation, Repos, work items, Boards, Test Plans, and Wiki commands.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Azure DevOps sheet](/shortcuts-cheatsheet-generator?apps=azure-devops)"},{"slug":"keyboard-shortcuts/balsamiq-wireframes","title":"<mark>Balsamiq Wireframes</mark> keyboard shortcuts","intro_markdown":"Balsamiq Wireframes combines direct-selection keys, drawing letters, and context-sensitive editing commands. Browser and operating-system shortcuts can take precedence in the web editor, so this reference keeps Balsamiq's published platform limits visible.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Balsamiq Wireframes sheet](/shortcuts-cheatsheet-generator?apps=balsamiq-wireframes)"},{"slug":"keyboard-shortcuts/basecamp","title":"<mark>Basecamp</mark> keyboard shortcuts","intro_markdown":"Basecamp 5 uses Shift-letter navigation throughout the web app, plus a small set of project and page commands. Hold Shift outside a text field to reveal available keycaps; inside a text field, press Shift twice to activate hotkey mode.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Basecamp sheet](/shortcuts-cheatsheet-generator?apps=basecamp)"},{"slug":"keyboard-shortcuts/bear","title":"<mark>Bear</mark> keyboard shortcuts","intro_markdown":"Bear for Mac has native commands for Markdown-style formatting, note structure, tables, navigation, and windows. Many bindings depend on whether focus is in the editor, note list, sidebar, or a table cell, so they are grouped by working context.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Bear sheet](/shortcuts-cheatsheet-generator?apps=bear)"},{"slug":"keyboard-shortcuts/bitbucket","title":"<mark>Bitbucket</mark> keyboard shortcuts","intro_markdown":"Bitbucket Cloud's documented keyboard shortcuts cover site search, navigation panels, repository file filtering, and the core pull-request review tabs and actions.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Bitbucket sheet](/shortcuts-cheatsheet-generator?apps=bitbucket)"},{"slug":"keyboard-shortcuts/blender","title":"<mark>Blender</mark> keyboard shortcuts","intro_markdown":"Blender's common default keymap covers file work, properties, selections, editor panels, 3D Viewport modes, animation keys, and Python data-path tools.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Blender sheet](/shortcuts-cheatsheet-generator?apps=blender)"},{"slug":"keyboard-shortcuts/bluebeam-revu","title":"<mark>Bluebeam Revu</mark> keyboard shortcuts","intro_markdown":"Bluebeam Revu's published Windows shortcuts cover markup creation and arrangement, measurement, PDF viewing, editing, page operations, panels, and document navigation.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Bluebeam Revu sheet](/shortcuts-cheatsheet-generator?apps=bluebeam-revu)"},{"slug":"keyboard-shortcuts/brave","title":"<mark>Brave Browser</mark> keyboard shortcuts","intro_markdown":"Brave keeps the useful browser controls close to the keyboard: move across tabs, jump to the address bar, search a page, or open browser tools without leaving the current window.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Brave Browser sheet](/shortcuts-cheatsheet-generator?apps=brave)"},{"slug":"keyboard-shortcuts/buffer","title":"<mark>Buffer</mark> keyboard shortcuts","intro_markdown":"Buffer's web shortcuts open its reference and command bar, jump among product areas, start new work, schedule posts, build threads, and navigate Community conversations.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Buffer sheet](/shortcuts-cheatsheet-generator?apps=buffer)"},{"slug":"keyboard-shortcuts/canva","title":"<mark>Canva</mark> keyboard shortcuts","intro_markdown":"Canva's editor uses shortcuts for creating elements, arranging and resizing selections, formatting text, changing page views, and handling comments. Desktop-app window and tab commands are separate from shortcuts that act inside a design.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Canva sheet](/shortcuts-cheatsheet-generator?apps=canva)"},{"slug":"keyboard-shortcuts/chrome","title":"<mark>Google Chrome</mark> keyboard shortcuts","intro_markdown":"Chrome's official list covers the browser habits that happen dozens of times a day: manage tabs, move through history, search the current page, reach browser tools, and work in the address bar without leaving the keyboard.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Google Chrome sheet](/shortcuts-cheatsheet-generator?apps=chrome)"},{"slug":"keyboard-shortcuts/cinema-4d","title":"<mark>Cinema 4D</mark> keyboard shortcuts","intro_markdown":"Cinema 4D's default shortcuts cover animation, project files, managers, the viewport, display modes, modeling and selection tools, rendering, and sculpt controls.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Cinema 4D sheet](/shortcuts-cheatsheet-generator?apps=cinema-4d)"},{"slug":"keyboard-shortcuts/claude-code","title":"<mark>Claude Code</mark> keyboard shortcuts","intro_markdown":"Claude Code spends most of its time waiting for a decision, running a tool, or holding a prompt. These official interactive-mode shortcuts cover interrupts, rewinds, mode changes, multiline input, terminal-style editing, and transcript navigation.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Claude Code sheet](/shortcuts-cheatsheet-generator?apps=claude-code)"},{"slug":"keyboard-shortcuts/clickup","title":"<mark>ClickUp</mark> keyboard shortcuts","intro_markdown":"ClickUp's official shortcut set covers workspace navigation, task creation, text editing, Chat, Inbox triage, views, SyncUps, and desktop-wide capture commands.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable ClickUp sheet](/shortcuts-cheatsheet-generator?apps=clickup)"},{"slug":"keyboard-shortcuts/clip-studio-paint","title":"<mark>Clip Studio Paint</mark> keyboard shortcuts","intro_markdown":"Clip Studio Paint assigns defaults to file, edit, layer, selection, canvas, and ruler commands. The defaults can be customized, so this reference describes the initial shortcut set rather than a user's edited configuration.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Clip Studio Paint sheet](/shortcuts-cheatsheet-generator?apps=clip-studio-paint)"},{"slug":"keyboard-shortcuts/clockify","title":"<mark>Clockify</mark> keyboard shortcuts","intro_markdown":"Clockify's web Time Tracker uses single keys when no field is being edited. The native Mac app has a separate set of Command shortcuts that work while its window has focus.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Clockify sheet](/shortcuts-cheatsheet-generator?apps=clockify)"},{"slug":"keyboard-shortcuts/coda","title":"<mark>Coda</mark> keyboard shortcuts","intro_markdown":"Coda combines document navigation, rich-text formatting, insert triggers, and table movement. Several keys change behavior with focus, so page, paragraph, and table commands are separated here.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Coda sheet](/shortcuts-cheatsheet-generator?apps=coda)"},{"slug":"keyboard-shortcuts/codex","title":"<mark>Codex CLI</mark> keyboard shortcuts","intro_markdown":"Codex CLI gives you a terminal UI around a running coding task. The current keymap covers steering, prompt editing, transcript navigation, reasoning effort, approvals, and the list pickers that appear around a session.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Codex CLI sheet](/shortcuts-cheatsheet-generator?apps=codex)"},{"slug":"keyboard-shortcuts/confluence","title":"<mark>Confluence</mark> keyboard shortcuts","intro_markdown":"Confluence Cloud has separate command sets for site navigation, pages and live docs, editor formatting, tables, Markdown input, and whiteboards. General shortcuts can be disabled in the in-product shortcut dialog.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Confluence sheet](/shortcuts-cheatsheet-generator?apps=confluence)"},{"slug":"keyboard-shortcuts/craft","title":"<mark>Craft</mark> keyboard shortcuts","intro_markdown":"Craft separates document navigation, task entry, block editing, formatting, organization, and tabs. Several commands are available only in the Mac app, so those bindings are kept platform-specific.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Craft sheet](/shortcuts-cheatsheet-generator?apps=craft)"},{"slug":"keyboard-shortcuts/cubase","title":"<mark>Steinberg Cubase</mark> keyboard shortcuts","intro_markdown":"Cubase Pro's current default key command reference covers project files, editing, transport, windows, and media. The platform-neutral commands are paired with the documented Windows and macOS modifier conventions.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Steinberg Cubase sheet](/shortcuts-cheatsheet-generator?apps=cubase)"},{"slug":"keyboard-shortcuts/cursor","title":"<mark>Cursor</mark> keyboard shortcuts","intro_markdown":"Cursor puts the editor and an AI workspace side by side. Its official reference covers chat, inline edit, code context, autocomplete, terminal prompts, model controls, and the familiar editor navigation keys around them.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable Cursor sheet](/shortcuts-cheatsheet-generator?apps=cursor)"},{"slug":"keyboard-shortcuts/davinci-resolve-fusion-page","title":"<mark>DaVinci Resolve Fusion Page</mark> keyboard shortcuts","intro_markdown":"The Fusion page uses a small set of transport and playhead commands for moving through a composition. The focused Fusion timeline or viewer determines where a command applies.","content_markdown":"<!-- section:print -->\n## Print the shortcuts you use\n\n[Make a printable DaVinci Resolve Fusion Page sheet](/shortcuts-cheatsheet-generator?apps=davinci-resolve-fusion-page)"},{"slug":"keyboard-shortcuts/davinci-resolve","title":"<mark>DaVinci Resolve</mark> keyboard shortcuts","intro_markdown":"These DaVinci Resolve commands cover playback, timeline navigation, timeline zoom, and the blade and clip-enable tools. Focus matters